begin;
alter table public.apostolic_armies drop constraint apostolic_armies_status_check;
alter table public.apostolic_armies add constraint apostolic_armies_status_check check(status in('ready','marching','stationed','returning','attacking'));
create table public.apostolic_city_attack_protections(city_id uuid primary key references public.apostolic_cities(id)on delete cascade,protected_until timestamptz not null,reason text not null,updated_at timestamptz not null default clock_timestamp());
create table public.apostolic_city_attacks(id uuid primary key default gen_random_uuid(),attacker_id uuid not null references public.profiles(id)on delete cascade,attacker_city_id uuid not null references public.apostolic_cities(id)on delete cascade,defender_city_id uuid not null references public.apostolic_cities(id)on delete cascade,army_id uuid not null references public.apostolic_armies(id)on delete restrict,status text not null default'prepared'check(status in('prepared','in_battle','resolved','expired')),battle_token uuid not null default gen_random_uuid()unique,result text check(result in('victory','defeat','draw')),prepared_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null,resolved_at timestamptz,idempotency_key uuid not null,unique(attacker_id,idempotency_key));
create unique index apostolic_one_active_attack_idx on public.apostolic_city_attacks(attacker_id)where status in('prepared','in_battle');
create index apostolic_attacks_defender_idx on public.apostolic_city_attacks(defender_city_id,prepared_at desc);
alter table public.apostolic_city_attack_protections enable row level security;alter table public.apostolic_city_attacks enable row level security;
create policy attack_protection_read on public.apostolic_city_attack_protections for select to authenticated using(true);create policy attacks_participants on public.apostolic_city_attacks for select to authenticated using(attacker_id=(select auth.uid())or exists(select 1 from public.apostolic_cities c where c.id=defender_city_id and c.owner_id=(select auth.uid())));
revoke all on public.apostolic_city_attack_protections,public.apostolic_city_attacks from anon,authenticated;grant select on public.apostolic_city_attack_protections,public.apostolic_city_attacks to authenticated;
create or replace function public.apostolic_get_attack_center()returns jsonb language sql stable security definer set search_path=''as $$with own as(select id,province_id from public.apostolic_cities where owner_id=(select auth.uid()))select jsonb_build_object('armies',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'total_units',total_units,'attack_power',attack_power,'status',status)),'[]'::jsonb)from public.apostolic_armies where owner_id=(select auth.uid())and status in('ready','stationed')),'targets',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'level',c.level,'slot',c.slot_no,'protected_until',p.protected_until)order by c.slot_no),'[]'::jsonb)from public.apostolic_cities c left join public.apostolic_city_attack_protections p on p.city_id=c.id and p.protected_until>clock_timestamp()where c.province_id=(select province_id from own)and c.id<>(select id from own)),'active',(select to_jsonb(x)from(select a.id,a.battle_token,a.status,a.expires_at,c.name target_name from public.apostolic_city_attacks a join public.apostolic_cities c on c.id=a.defender_city_id where a.attacker_id=(select auth.uid())and a.status in('prepared','in_battle')limit 1)x),'history',(select coalesce(jsonb_agg(to_jsonb(h)order by resolved_at desc),'[]'::jsonb)from(select c.name target_name,a.result,a.resolved_at from public.apostolic_city_attacks a join public.apostolic_cities c on c.id=a.defender_city_id where a.attacker_id=(select auth.uid())and a.status='resolved'order by a.resolved_at desc limit 10)h))$$;
create or replace function public.apostolic_prepare_city_attack(p_army_id uuid,p_defender_city_id uuid,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());a public.apostolic_armies%rowtype;home public.apostolic_cities%rowtype;target public.apostolic_cities%rowtype;aid uuid;begin if uid is null or p_idempotency_key is null then raise exception'authentication required';end if;select*into a from public.apostolic_armies where id=p_army_id and owner_id=uid for update;if not found or a.status not in('ready','stationed')then raise exception'army unavailable';end if;select*into home from public.apostolic_cities where id=a.home_city_id;select*into target from public.apostolic_cities where id=p_defender_city_id;if not found or target.province_id<>home.province_id or target.owner_id=uid then raise exception'invalid target';end if;if exists(select 1 from public.apostolic_city_attack_protections where city_id=target.id and protected_until>clock_timestamp())then raise exception'target protected';end if;if exists(select 1 from public.apostolic_city_attacks where attacker_id=uid and idempotency_key=p_idempotency_key)then return public.apostolic_get_attack_center();end if;if exists(select 1 from public.apostolic_city_attacks where attacker_id=uid and status in('prepared','in_battle'))then raise exception'attack already active';end if;insert into public.apostolic_city_attacks(attacker_id,attacker_city_id,defender_city_id,army_id,expires_at,idempotency_key)values(uid,home.id,target.id,a.id,clock_timestamp()+interval'15 minutes',p_idempotency_key)returning id into aid;update public.apostolic_armies set status='attacking'where id=a.id;return public.apostolic_get_attack_center();end;$$;
create or replace function public.apostolic_begin_city_attack(p_attack_id uuid,p_battle_token uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.apostolic_city_attacks%rowtype;begin select*into a from public.apostolic_city_attacks where id=p_attack_id and attacker_id=(select auth.uid())for update;if not found or a.battle_token<>p_battle_token or a.status not in('prepared','in_battle')or a.expires_at<=clock_timestamp()then raise exception'attack unavailable';end if;update public.apostolic_city_attacks set status='in_battle'where id=a.id;return jsonb_build_object('attack_id',a.id,'battle_token',a.battle_token);end;$$;
create or replace function public.apostolic_resolve_city_attack(p_attack_id uuid,p_battle_token uuid,p_result text)returns jsonb language plpgsql security definer set search_path=''as $$declare a public.apostolic_city_attacks%rowtype;begin if p_result not in('victory','defeat','draw')then raise exception'invalid result';end if;select*into a from public.apostolic_city_attacks where id=p_attack_id and attacker_id=(select auth.uid())for update;if not found or a.battle_token<>p_battle_token then raise exception'attack unavailable';end if;if a.status='resolved'then return public.apostolic_get_attack_center();end if;if a.status<>'in_battle'or a.expires_at<=clock_timestamp()then raise exception'attack expired';end if;update public.apostolic_city_attacks set status='resolved',result=p_result,resolved_at=clock_timestamp()where id=a.id;update public.apostolic_armies set status='ready'where id=a.army_id;insert into public.apostolic_city_attack_protections(city_id,protected_until,reason)values(a.defender_city_id,clock_timestamp()+case when p_result='victory'then interval'30 minutes'else interval'10 minutes'end,'post_battle')on conflict(city_id)do update set protected_until=greatest(public.apostolic_city_attack_protections.protected_until,excluded.protected_until),updated_at=clock_timestamp();return public.apostolic_get_attack_center();end;$$;
revoke all on function public.apostolic_get_attack_center(),public.apostolic_prepare_city_attack(uuid,uuid,uuid),public.apostolic_begin_city_attack(uuid,uuid),public.apostolic_resolve_city_attack(uuid,uuid,text)from public;grant execute on function public.apostolic_get_attack_center(),public.apostolic_prepare_city_attack(uuid,uuid,uuid),public.apostolic_begin_city_attack(uuid,uuid),public.apostolic_resolve_city_attack(uuid,uuid,text)to authenticated;commit;
